package eg.englishsavant.matrix;
import android.app.*;import android.os.*;import android.content.*;import android.webkit.*;import android.view.*;import java.io.*;import java.util.concurrent.*;
public class MatrixAudit extends Instrumentation {
 Activity activity;WebView web;File out;Bundle args;StringBuilder log=new StringBuilder();
 public void callActivityOnResume(Activity a){super.callActivityOnResume(a);activity=a;web=find(a.getWindow().getDecorView());}
 public void onCreate(Bundle b){super.onCreate(b);args=b;start();}
 WebView find(View v){if(v instanceof WebView)return (WebView)v;if(v instanceof android.view.ViewGroup){android.view.ViewGroup g=(android.view.ViewGroup)v;for(int i=0;i<g.getChildCount();i++){WebView w=find(g.getChildAt(i));if(w!=null)return w;}}return null;}
 String js(String s)throws Exception{CountDownLatch d=new CountDownLatch(1);String[] r={"null"};runOnMainSync(()->web.evaluateJavascript(s,v->{r[0]=v;d.countDown();}));if(!d.await(4,TimeUnit.SECONDS))throw new IOException("JS timeout");return r[0];}
 void shell(String s)throws Exception{android.os.ParcelFileDescriptor p=getUiAutomation().executeShellCommand(s);try(InputStream in=new android.os.ParcelFileDescriptor.AutoCloseInputStream(p)){while(in.read()!=-1){}}}
 void save(String n,String s)throws Exception{try(FileOutputStream f=new FileOutputStream(new File(out,n))){f.write(s.getBytes("UTF-8"));}}
 void shot(String n)throws Exception{Thread.sleep(1800);getUiAutomation().waitForIdle(300,3000);Thread.sleep(400);android.graphics.Bitmap b=getUiAutomation().takeScreenshot();try(FileOutputStream f=new FileOutputStream(new File(out,n+".png"))){b.compress(android.graphics.Bitmap.CompressFormat.PNG,100,f);}try{save(n+".json",js("JSON.stringify({url:location.href,ua:navigator.userAgent,w:innerWidth,h:innerHeight,dpr:devicePixelRatio,sw:document.documentElement.scrollWidth,language:document.documentElement.dataset.interfaceLanguage,dark:document.body.classList.contains('dark'),header:(()=>{let x=document.querySelector('header');return x&&x.getBoundingClientRect().toJSON()})(),search:(()=>{let x=document.querySelector('.es-site-search-wrap');return x&&x.getBoundingClientRect().toJSON()})(),body:document.body.innerText.slice(0,14000),video:(()=>{let x=document.querySelector('video');return x&&{time:x.currentTime,paused:x.paused,error:x.error&&x.error.code}})()})"));}catch(Exception e){save(n+"-error.txt",e.toString());}}
 void open(String p)throws Exception{runOnMainSync(()->web=find(activity.getWindow().getDecorView()));String url="https://basemhreaz-cloud.github.io/english-savant/"+p;runOnMainSync(()->web.loadUrl(url));for(int i=0;i<180;i++){Thread.sleep(500);String r=js("!!(document.querySelector('#nav')&&document.querySelector('.menu-toggle')&&document.querySelector('.es-menu-backdrop')&&window.ESInterface)");if("true".equals(r))return;}throw new IOException("Page timeout "+p);}
 void configure(String lang,boolean dark)throws Exception{js("window.ESInterface&&ESInterface.setLanguage('"+lang+"');document.body.classList.toggle('dark',"+dark+");window.scrollTo(0,0);window.dispatchEvent(new Event('resize'))");Thread.sleep(450);}
 void tap(String selector)throws Exception{String v=js("(()=>{let e=document.querySelector("+org.json.JSONObject.quote(selector)+");if(!e)return null;e.scrollIntoView({block:'center'});let r=e.getBoundingClientRect();return {x:(r.x+r.width/2)*devicePixelRatio,y:(r.y+r.height/2)*devicePixelRatio}})()");if("null".equals(v))throw new IOException("No selector "+selector);org.json.JSONObject p=new org.json.JSONObject(v);int[] loc=new int[2];runOnMainSync(()->web.getLocationOnScreen(loc));long t=SystemClock.uptimeMillis();sendPointerSync(MotionEvent.obtain(t,t,0,(float)p.getDouble("x")+loc[0],(float)p.getDouble("y")+loc[1],0));sendPointerSync(MotionEvent.obtain(t,t+60,1,(float)p.getDouble("x")+loc[0],(float)p.getDouble("y")+loc[1],0));}
 void screen(String name,String path,String lang,boolean dark)throws Exception{try{open(path);configure(lang,dark);if(name.equals("windows"))js("document.querySelector('#windows-install')&&document.querySelector('#windows-install').scrollIntoView({block:'center'})");if(name.equals("quiz")){try{tap(".lesson-choice");Thread.sleep(600);}catch(Exception ignored){}}if(name.equals("video")){try{tap("video");Thread.sleep(3500);}catch(Exception ignored){}}shot(name+"-"+lang+"-"+(dark?"dark":"light"));if(name.equals("home")){shell("input swipe 500 350 500 100 500");Thread.sleep(600);shot("home-scrolled-"+lang+"-"+dark);}}catch(Exception e){save(name+"-"+lang+"-"+dark+"-error.txt",e.toString());}}
 public void onStart(){out=new File(getTargetContext().getFilesDir(),"matrix");out.mkdirs();try{activity=startActivitySync(new Intent().setClassName("eg.englishsavant.app","eg.englishsavant.app.MainActivity").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));for(int i=0;i<90;i++){runOnMainSync(()->web=find(activity.getWindow().getDecorView()));if(web!=null)break;Thread.sleep(1000);}if(web==null){shot("native-window-no-webview");throw new IOException("WebView absent");}Thread.sleep(12000);shot("native-installed-start");
 shell("svc wifi disable");shell("svc data disable");save("network-offline.txt","Wifi and mobile data disabled before page tests");
 for(String lang:new String[]{"ar","en"})for(boolean dark:new boolean[]{false,true}){String label=lang+"-"+(dark?"dark":"light");open("grade-p1.html");configure(lang,dark);tap(".menu-toggle");Thread.sleep(1800);if(!"true".equals(js("document.querySelector('#nav').classList.contains('open')")))throw new IOException("Menu did not open");shot("menu-"+label);shot("menu-confirm-"+label);save("menu-state-"+label+".json",js("JSON.stringify((function(){var n=document.querySelector('#nav'),s=document.querySelector('.es-site-search-wrap'),v=document.querySelector('.es-menu-backdrop'),a=n&&n.querySelectorAll('a'),rows=[],i;for(i=0;a&&i<a.length;i++){var c=getComputedStyle(a[i]);rows.push({text:a[i].innerText,bg:c.backgroundColor,border:c.borderWidth,radius:c.borderRadius,shadow:c.boxShadow,after:getComputedStyle(a[i],'::after').content})}return {ua:navigator.userAgent,offline:!navigator.onLine,url:location.href,menuOpen:n&&n.classList.contains('open'),panel:n&&getComputedStyle(n).backgroundColor,links:rows,searchFilter:s&&getComputedStyle(s).filter,veilHidden:v&&v.hidden,veilColor:v&&getComputedStyle(v).backgroundColor,backdrop:v&&(getComputedStyle(v).backdropFilter||getComputedStyle(v).webkitBackdropFilter),width:innerWidth,scrollWidth:document.documentElement.scrollWidth,lang:document.documentElement.getAttribute('data-interface-language')};})())"));tap(".menu-toggle");Thread.sleep(200);tap(".es-site-search-wrap input");Thread.sleep(1800);shot("search-"+label);shot("search-confirm-"+label);save("search-state-"+label+".json",js("JSON.stringify((function(){var n=document.querySelector('#nav'),s=document.querySelector('.es-site-search-wrap'),v=document.querySelector('.es-menu-backdrop'),a=n&&n.querySelectorAll('a'),rows=[],i;for(i=0;a&&i<a.length;i++){var c=getComputedStyle(a[i]);rows.push({text:a[i].innerText,bg:c.backgroundColor,border:c.borderWidth,radius:c.borderRadius,shadow:c.boxShadow,after:getComputedStyle(a[i],'::after').content})}return {ua:navigator.userAgent,offline:!navigator.onLine,url:location.href,menuOpen:n&&n.classList.contains('open'),panel:n&&getComputedStyle(n).backgroundColor,links:rows,searchFilter:s&&getComputedStyle(s).filter,veilHidden:v&&v.hidden,veilColor:v&&getComputedStyle(v).backgroundColor,backdrop:v&&(getComputedStyle(v).backdropFilter||getComputedStyle(v).webkitBackdropFilter),width:innerWidth,scrollWidth:document.documentElement.scrollWidth,lang:document.documentElement.getAttribute('data-interface-language')};})())"));}
 save("summary.txt","Real Android emulator screenshots. Target APK re-signed for test instrumentation only; production DEX/resources unchanged. Native navigation and font/orientation values recorded by runner. WebView URL loads used for deterministic page coverage; video/PDF use native input taps. Not physical-device certification.");
 }catch(Throwable e){try{save("harness-error.txt",e.toString());}catch(Exception ignored){}}finally{try{shell("settings put system font_scale 1.0");}catch(Exception ignored){}finish(Activity.RESULT_OK,new Bundle());}}
}
